executeCodeConfig.code:
const taskId = $flow.inParams.taskId;
const priorityId = $flow.inParams.priority_id;
if (!$utils.isDefined(taskId) || !$utils.isDefined(priorityId)) {
    throw new Error('taskId and priority_id are required.');
}
try {
    await $flows.Utilities.crud_update_entity({ entity: 'Tasks', keys: [{ name: 'Id', value: taskId }], properties: { PriorityId: priorityId } });
} catch (e) {
    throw new Error(`Failed to update task ${taskId}: ${e.message}`);
}
$flow.outParams.result_message = `Task ${taskId} priority set to ${priorityId}.`;
